const b = $input.first().json.body || $input.first().json || {};
const hist = Array.isArray(b.history) ? b.history.filter(h => h && h.text).slice(-10) : [];
const normIds = function(v){ if (v === undefined || v === null || v === '') return []; const a = Array.isArray(v) ? v : [v]; return a.map(function(x){ return parseInt(x); }).filter(function(x){ return x > 0; }); };
return [{ json: { text: (b.text || '').toString().slice(0, 2000),
  userId: (b.userId || '').toString(),
  channel: (b.channel || '').toString(),
  group_id: b.group_id ? parseInt(b.group_id) : null,
  group_ids: normIds(b.group_ids !== undefined ? b.group_ids : b.group_id),
  session_id: (b.session_id || 'ai-' + Date.now()).toString(),
  history: hist } }];

const g = $('Prep').first().json;
const ch = (g.channel || '').toString();
const esc = (s) => (s || '').toString().replace(/'/g, "''");
const norm = function(v){ if (v === undefined || v === null || v === '') return []; const a = Array.isArray(v) ? v : [v]; return a.map(function(x){ return parseInt(x); }).filter(function(x){ return x > 0; }); };
if (ch && /^[a-z0-9_]{2,32}$/.test(ch)) {
  return [{ json: { sql: `SELECT COALESCE((SELECT persona_system FROM channel_map WHERE channel_code = '${esc(ch)}'), '') AS persona, COALESCE((SELECT json_agg(group_id ORDER BY group_id) FROM channel_rag_groups WHERE channel_code = '${esc(ch)}'), '[]') AS group_ids` } }];
}
const gids = norm(g.group_ids !== undefined && g.group_ids !== null ? g.group_ids : g.group_id);
return [{ json: { sql: `SELECT '' AS persona, '${JSON.stringify(gids)}' AS group_ids` } }];

const orig = $('Prep').first().json;
const r = $input.first().json;
const FALLBACK = 'ไม่พบข้อมูลนี้ในฐานความรู้';
const use_rag = !!(r && r.ok && r.text && r.text.indexOf(FALLBACK) < 0 && (r.sources || []).length);
return [{ json: { ...orig, use_rag: use_rag,
  rag_text: use_rag ? r.text : '', rag_images: use_rag ? (r.images || []) : [],
  rag_sources: use_rag ? (r.sources || []) : [] } }];

const j = $input.first().json;
return [{ json: { ok: true, text: j.rag_text, images: j.rag_images || [],
  sources: j.rag_sources || [], via: 'rag' } }];

const j = $input.first().json;
const GEM = "คุณคือผู้ช่วยจองที่พักของเว็บ TripThai พูดภาษาไทยสุภาพเป็นกันเอง ตอบสั้นกระชับเหมาะกับการฟังออกเสียง (ไม่เกิน 3-4 ประโยค) ห้ามใช้ markdown ตาราง โค้ด หรืออีโมจิ ข้อมูลเว็บ: โค้ด TRIPTHAI100 ลด 100 บาท, ที่พักเริ่ม 1,400 บาท/คืน, หลายรายการยกเลิกฟรี, จังหวัดยอดนิยม: กรุงเทพฯ เชียงใหม่ ภูเก็ต พัทยา กระบี่ หัวหิน เกาะสมุย เชียงราย ถ้าถูกถามเรื่องที่ไม่มีข้อมูล ให้บอกว่าจะส่งต่อให้เจ้าหน้าที่ช่วยเหลือ";
const sys = (() => { try { const p = ($('Run Persona').first().json.persona || '').trim(); return p ? p : GEM; } catch(e) { return GEM; } })();
const contents = [];
(j.history || []).forEach(h => {
  const t = (h.text || '').toString().trim().slice(0, 1000);
  if (!t) return;
  contents.push({ role: h.role === 'model' ? 'model' : 'user', parts: [{ text: t }] });
});
while (contents.length && contents[0].role !== 'user') contents.shift();
contents.push({ role: 'user', parts: [{ text: j.text }] });
return [{ json: { body: { system_instruction: { parts: [{ text: sys }] }, contents: contents,
  generationConfig: { maxOutputTokens: 1024, temperature: 0.7 } } } }];

const it = $input.first().json;
let t = '';
try { t = it.candidates[0].content.parts.map(p => p.text || '').join(''); } catch(e) {}
t = t.trim();
if (!t) throw new Error('Gemini ไม่ตอบ');
return [{ json: { ok: true, text: t.slice(0, 2000), images: [], sources: [], via: 'gemini' } }];

const j = $input.first().json;
const GEM = "คุณคือผู้ช่วยจองที่พักของเว็บ TripThai พูดภาษาไทยสุภาพเป็นกันเอง ตอบสั้นกระชับเหมาะกับการฟังออกเสียง (ไม่เกิน 3-4 ประโยค) ห้ามใช้ markdown ตาราง โค้ด หรืออีโมจิ ข้อมูลเว็บ: โค้ด TRIPTHAI100 ลด 100 บาท, ที่พักเริ่ม 1,400 บาท/คืน, หลายรายการยกเลิกฟรี, จังหวัดยอดนิยม: กรุงเทพฯ เชียงใหม่ ภูเก็ต พัทยา กระบี่ หัวหิน เกาะสมุย เชียงราย ถ้าถูกถามเรื่องที่ไม่มีข้อมูล ให้บอกว่าจะส่งต่อให้เจ้าหน้าที่ช่วยเหลือ";
const per = (() => { try { const p = ($('Run Persona').first().json.persona || '').trim(); return p ? p : GEM; } catch(e) { return GEM; } })();
const msgs = [];
(j.history || []).forEach(h => {
  const t = (h.text || '').toString().trim().slice(0, 1000);
  if (!t) return;
  msgs.push({ role: h.role === 'model' ? 'assistant' : 'user', content: t });
});
while (msgs.length && msgs[0].role !== 'user') msgs.shift();
msgs.push({ role: 'user', content: j.text });
return [{ json: { messages: msgs, system: per + ' /no_think' } }];

const it = $input.first().json;
let t = '';
try { t = ((it.message || {}).content || '').toString(); } catch(e) {}
t = t.replace(/^[\s\S]*?<\/think>/, '').replace(/<think>[\s\S]*?<\/think>/g, '').trim();
if (!t) throw new Error('Local LLM ไม่ตอบ');
return [{ json: { ok: true, text: t.slice(0, 2000), images: [], sources: [], via: 'qwen3:4b' } }];
